const reduce=matchMedia('(prefers-reduced-motion: reduce)');
const video=document.querySelector('#intro-video'),play=document.querySelector('#play'),icon=document.querySelector('#play-icon'),label=document.querySelector('.presenter-label');
play.onclick=async()=>{if(video.paused){try{await video.play()}catch{label.textContent='播放失败，请再次点击'}}else video.pause()};
video.addEventListener('play',()=>{play.classList.add('playing');play.setAttribute('aria-label','暂停自我介绍');icon.textContent='Ⅱ';label.textContent='自我介绍 · 点击暂停'});
video.addEventListener('pause',()=>{play.classList.remove('playing');play.setAttribute('aria-label','播放自我介绍');icon.textContent='▶';label.textContent='听我介绍 · 点击播放'});
video.addEventListener('timeupdate',()=>{const s=Math.floor(video.currentTime);document.querySelector('#time').textContent=Math.floor(s/60)+':'+String(s%60).padStart(2,'0')});
document.querySelector('#mute').onclick=e=>{video.muted=!video.muted;e.currentTarget.textContent=video.muted?'声音关':'声音开';e.currentTarget.setAttribute('aria-label',video.muted?'开启声音':'静音')};
document.querySelector('#close-presenter').onclick=()=>{video.pause();document.querySelector('#presenter').hidden=true;document.querySelector('#restore').hidden=false;document.querySelector('#restore').focus()};
document.querySelector('#restore').onclick=()=>{document.querySelector('#presenter').hidden=false;document.querySelector('#restore').hidden=true;play.focus()};
const box=document.querySelector('#lightbox');document.querySelectorAll('.zoom').forEach(button=>button.onclick=()=>{box.querySelector('img').src=button.querySelector('img').src;box.querySelector('img').alt=button.querySelector('img').alt;box.querySelector('p').textContent=button.dataset.caption;box.showModal()});document.querySelector('#close-lightbox').onclick=()=>box.close();box.addEventListener('click',e=>{if(e.target===box)box.close()});
let returnFocus=null,readerHash=false;
function showCase(hash,update=true){const dialog=document.getElementById(hash.replace('#',''));if(!dialog?.classList.contains('case-reader'))return;document.querySelectorAll('.case-reader[open]').forEach(d=>d.close());dialog.showModal();dialog.scrollTop=0;readerHash=true;if(update)history.pushState(null,'',hash);}
document.querySelectorAll('a[href^="#case-"]').forEach(a=>a.onclick=e=>{e.preventDefault();if(!document.querySelector('.case-reader[open]'))returnFocus=a;showCase(a.hash)});
function closeCase(){document.querySelectorAll('.case-reader[open]').forEach(d=>d.close());if(readerHash){history.replaceState(null,'','#work');readerHash=false}returnFocus?.focus({preventScroll:true});}
document.querySelectorAll('.case-reader').forEach(d=>{d.querySelector('.close-case').onclick=closeCase;d.addEventListener('cancel',e=>{e.preventDefault();closeCase()});d.addEventListener('click',e=>{if(e.target===d)closeCase()})});
addEventListener('popstate',()=>{if(location.hash.startsWith('#case-'))showCase(location.hash,false);else closeCase()});if(location.hash.startsWith('#case-'))showCase(location.hash,false);
const steps=[...document.querySelectorAll('.project-step')],frames=[...document.querySelectorAll('.stage-frame')];let active=-1;
function activate(i){if(i===active)return;active=i;steps.forEach((s,j)=>s.classList.toggle('selected',i===j));frames.forEach((f,j)=>{f.classList.toggle('active',i===j);f.setAttribute('aria-hidden',i!==j)});document.querySelector('#stage-number').textContent=String(i+1).padStart(2,'0');document.querySelector('.stage-track i').style.transform=`translateX(${i*100}%)`;}
steps.forEach((s,i)=>{s.addEventListener('mouseenter',()=>activate(i));s.addEventListener('focusin',()=>activate(i))});
const hero=document.querySelector('.hero'),poster=document.querySelector('#hero-poster'),canvas=document.querySelector('#poster-particles'),ctx=canvas.getContext('2d');let particles=[];
function makeParticles(){const w=260,h=Math.round(w*poster.naturalHeight/poster.naturalWidth);const sample=document.createElement('canvas');sample.width=w;sample.height=h;const c=sample.getContext('2d');c.drawImage(poster,0,0,w,h);const data=c.getImageData(0,0,w,h).data;particles=[];for(let y=0;y<h;y+=5)for(let x=0;x<w;x+=5){const k=(y*w+x)*4;if(data[k]<220&&data[k+1]<170)particles.push({x:x/w,y:y/h,r:data[k],g:data[k+1],b:data[k+2],dx:Math.sin(x*12.99+y*78.23),dy:Math.cos(x*5.17+y*31.31)})}canvas.width=600;canvas.height=720;}
if(poster.complete&&poster.naturalWidth)makeParticles();else poster.addEventListener('load',makeParticles);
function drawParticles(p){ctx.clearRect(0,0,600,720);if(p<=0||p>=1)return;const w=600/2.2,h=720/2,x0=(600-w)/2,y0=180;particles.forEach(a=>{ctx.fillStyle=`rgba(${a.r},${a.g},${a.b},${(1-p)*.9})`;ctx.fillRect(x0+a.x*w+a.dx*p*p*350,y0+a.y*h+a.dy*p*p*330,Math.max(1,4*(1-p)),Math.max(1,4*(1-p)))})}
let pending=false;
function updateMotion(){pending=false;const rect=hero.getBoundingClientRect(),p=Math.max(0,Math.min(1,-rect.top/(rect.height*.8)));let nearest=0,dist=Infinity;steps.forEach((s,i)=>{const d=Math.abs(s.getBoundingClientRect().top+s.offsetHeight*.4-innerHeight*.5);if(d<dist){nearest=i;dist=d}});activate(nearest);if(!reduce.matches){hero.style.setProperty('--hero-progress',p);document.querySelectorAll('.hero h1>span').forEach((el,i)=>{el.style.transform=`translateX(${p*(i%2?50:-70)}px)`;el.style.opacity=Math.max(.2,1-p*.8)});const spread=Math.max(0,Math.min(1,(p-.08)/.8));poster.style.opacity=Math.max(0,1-spread*3);canvas.style.opacity=spread>0?1:0;drawParticles(spread);document.querySelector('.hero-aside').style.transform=`translateY(${p*40}px) rotate(${4-p*12}deg)`;document.querySelectorAll('.gallery figure').forEach((el,i)=>{const y=el.getBoundingClientRect().top;el.style.transform=`translateY(${Math.max(-30,Math.min(30,(y-innerHeight*.5)*.07))*(i%2?-1:1)}px)`})}else{poster.style.opacity=1;canvas.style.opacity=0;document.querySelectorAll('.hero h1>span').forEach(el=>{el.style.transform='';el.style.opacity=1})}}
function queue(){if(!pending){pending=true;requestAnimationFrame(updateMotion)}}addEventListener('scroll',queue,{passive:true});addEventListener('resize',queue);reduce.addEventListener('change',queue);queue();
if(!reduce.matches){document.documentElement.classList.add('js-motion');const io=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('in-view',e.isIntersecting)),{threshold:.15});document.querySelectorAll('.case-image').forEach(e=>io.observe(e))}
